mapper.select:
select  from takeout_merchant m
left join sys_user u on u.user_id = m.owner_user_id
where m.del_flag = '0'
and m.merchant_id = #{merchantId}
and m.owner_user_id = #{ownerUserId}
and m.merchant_name like concat('%', #{merchantName}, '%')
and m.status = #{status}
order by m.create_time desc, m.merchant_id desc

mapper.update:
update takeout_merchant
merchant_name = #{merchantName}, owner_user_id = #{ownerUserId}, contact_phone = #{contactPhone}, logo = #{logo}, address = #{address}, open_time = #{openTime}, close_time = #{closeTime}, notice = #{notice}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate(), version = version + 1
where merchant_id = #{merchantId} and del_flag = '0' and version = #{version}
